// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }
    function testFuzz_property(address actor, uint128 amount) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(amount > 0);
        uint256 priorUnlock;
        uint256 priorBalance;
        (priorUnlock, priorBalance) = c.Acc(actor);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(block.timestamp + amount + 1);
        uint256 newUnlock;
        uint256 newBalance;
        (newUnlock, newBalance) = c.Acc(actor);
        assertTrue(newBalance == priorBalance + amount && address(c).balance >= amount);
    }
}
